-- Written to be re-runnable: production applies each statement on its own, so a run
-- interrupted part way must be able to start again from the top.
-- Web Push (WP-PIC18): one table for the browsers a person chose to get alerts on. Additive,
-- nothing existing is touched, no backfill. The push address and keys are sealed by the app; only
-- a hash of the address is in the clear. Generated by drizzle-kit and made re-runnable here.
-- Until this runs the code finds the table missing and the feature stays hidden.
CREATE TABLE IF NOT EXISTS "web_push_subscriptions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"account_id" uuid NOT NULL,
	"endpoint_hash" text NOT NULL,
	"endpoint_ciphertext" "bytea" NOT NULL,
	"endpoint_nonce" "bytea" NOT NULL,
	"keys_ciphertext" "bytea" NOT NULL,
	"keys_nonce" "bytea" NOT NULL,
	"key_version" text NOT NULL,
	"session_ref" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_success_at" timestamp with time zone,
	"failure_count" integer DEFAULT 0 NOT NULL,
	"renewed_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "web_push_subscriptions_endpoint_unique" UNIQUE("endpoint_hash"),
	CONSTRAINT "web_push_subscriptions_failures_nonnegative" CHECK ("web_push_subscriptions"."failure_count" >= 0)
);
